SPECIAL_SOUL_IMPACT_NOTIFICATION_DESCRIPTION = "Giáng luồng năng lượng linh hồn mạnh mẽ từ trên cao xuống kẻ địch.",
SPECIAL_SOUL_IMPACT_NAME = "Xung kích linh hồn",
SPECIAL_UNLOCKED = "Đã mở kỹ năng đặc biệt",
STAGE_0_DESCRIPTION = "Cuối cùng ta đã tự do! Không thể chờ thêm nữa, phải trở về tháp ngay! Nhưng... tháp của ta đâu?! Cái quái gì thế này?! Denas! Chắc chắn là tên vua thối nát đó! Hắn đã làm gì trong lúc ta vắng mặt?",
STAGE_0_TITLE = "Tháp của Vez'nan",
STAGE_1_DESCRIPTION = "Tốt lắm! Tháp của ta đã trở lại vẻ huy hoàng xưa kia. Giờ đến lúc lên đường! Lũ người lùn ngu ngốc chỉ mải tìm kho báu, chẳng biết ta đang chờ chúng. Tướng quân, hãy chứng minh ngươi không vô dụng: dẫn quân của ta bắt đầu cuộc chinh phạt!",
STAGE_1_NAME = "Cửa của con rắn",
STAGE_10_DESCRIPTION = "Đồ vô dụng! Ngươi đã để tên Vua phương Bắc cưỡi rồng trốn thoát! Phải đuổi kịp và hạ hắn trên núi. Ta cảm thấy bão tuyết đang đến. Hành động ngay, đừng để bão hay lũ sinh vật khó chịu kia phá hỏng kế hoạch của ta!",
STAGE_10_TITLE = "Trại trộm rồng",
STAGE_11_DESCRIPTION = "Cuối cùng cũng đến đỉnh núi! Từ đây ta đã nhìn thấy Linirea. Ha! Lũ ngu ngốc kia vẫn còn lớn tiếng dù sắp tận số. Tướng quân, Arkuz đã bị dồn vào đường cùng. Đây là cơ hội để ngươi chuộc lỗi. Đừng bỏ lỡ!",
STAGE_11_NAME = "Băng thang bay",
STAGE_12_DESCRIPTION = "Tốt lắm! Ngươi có cảm thấy sự yên ắng trước cơn bão không? Otil vẫn chưa biết chuyện gì sắp ập đến, nhưng chúng ta biết. Ha ha! Đây là nơi đóng trại lý tưởng. Cơ hội đã tới, hãy nắm lấy!",
STAGE_12_NAME = "Nông nghiệp Othel",
STAGE_13_DESCRIPTION = "Ha ha! Dễ như lấy kẹo của trẻ con! Thị trấn nhỏ đã thất thủ, quân ta nóng lòng tiến tới chiến thắng tiếp theo. Giờ đến lượt lũ tai nhọn! Xuyên qua Silveroak và cho các cung thủ hèn nhát cùng thủ lĩnh Alleria thấy sức mạnh của quân đội hắc ám!",
STAGE_13_NAME = "Trạm tiền bạc",
STAGE_14_DESCRIPTION = "Đúng như ta dự đoán, lũ tinh linh đã bị quét sạch. Giờ đến lượt Lozagon biết ai mới là chủ nhân thật sự. Chiếm thành phố này, ta sẽ vượt qua kết giới quanh lâu đài Denas. Cẩn thận, tướng quân: Magnus, học trò cũ của ta, đang bảo vệ nơi đây. Cho tên học trò bất tài ấy thấy sức mạnh ma thuật thực thụ!",
STAGE_14_NAME = "Thành phố Lozagón",
STAGE_15_DESCRIPTION = "Đã hạ được hai kẻ, chỉ còn một! Mọi thứ đã rất gần, ta gần như nếm được vị ngọt chiến thắng. Gerald đang đợi phía trước, nhưng hắn có vẻ quá bình thản. Tên anh hùng già đó chẳng coi ta ra gì sao? Bắt sống hắn về đây! Ta sẽ cho hắn thấy sự thật đằng sau những lời dối trá!",
STAGE_15_TITLE = "Khu trại ánh sáng",
STAGE_16_DESCRIPTION = "Ngươi đến được đây là khá lắm, tướng quân! Tiếng kêu của chúng nghe thật êm tai, như khúc nhạc báo trước chiến thắng của ta. Hãy đối mặt thử thách cuối cùng! Quân ta đã tới cổng thành, hãy cho lũ ngu biết ai mới xứng đáng cai trị. Thắng trận này, giao ước giữa ngươi và ta sẽ hoàn tất!",
STAGE_16_TITLE = "Lâu đài Denas",
STAGE_2_DESCRIPTION = "Chúng nghĩ những cánh cổng mong manh này có thể ngăn quân ta sao? Ha! Ta có thể chiếm thành phố cũ kỹ này trong vài phút. Đừng bỏ lỡ cơ hội! Lực lượng phòng thủ chỉ là một nhóm yếu ớt, ngay cả ngươi cũng dễ dàng đánh bại.",
STAGE_2_NAME = "Cảng Thành Phố Cũ",
STAGE_3_DESCRIPTION = "Chà, một khu mỏ khá đấy. Nếu là ta, nơi này hẳn còn tốt hơn! Nó cung cấp đủ vũ khí cho quân đội người lùn. Tướng quân, đừng nói ngươi sẽ chịu thua đám thợ mỏ nhé!",
STAGE_3_NAME = "Khu khai thác Kazan",
STAGE_4_DESCRIPTION = "Ha ha! Trinh sát của ta đã bỏ thuốc vào thức ăn của chúng mà lũ người lùn chẳng hề hay biết. Giờ chúng yếu hơn trước nhiều! Hãy tận dụng cơ hội. Cho binh sĩ uống vài thùng bia, chúng cũng cần được nghỉ ngơi sau hành quân.",
STAGE_4_NAME = "Cà phê vàng",
STAGE_5_DESCRIPTION = "Ồn ào quá! Nhà máy này lúc nào cũng rầm rĩ, phải đóng cửa nó ngay! Mà khoan... những cỗ máy tự động ấy có vẻ hữu ích. Chiếm nhà máy cho ta! Thân thép của chúng có thể cản đao kiếm, nhưng không cản nổi ma thuật của ta.",
STAGE_5_TITLE = "Nhà máy phát",
STAGE_6_DESCRIPTION = "Ngai vàng đã ở ngay trước mắt! Nhìn xem, chúng gom tất cả kho báu vào một chỗ để ta lấy cho tiện. Và Bolgur, vua người lùn, vẫn ung dung ngồi đó. Tướng quân, hãy xóa nụ cười trên mặt hắn và chiếm ngai vàng!",
STAGE_6_TITLE = "Thượng đế của Bogu",
STAGE_7_DESCRIPTION = "Đó mới chỉ là bài học đầu tiên! Với nguồn tài nguyên mới, cả vương quốc sẽ phải run sợ trước quân ta. Giờ hãy tiến lên miền Bắc băng giá, nơi lũ người phương Bắc tưởng mình mạnh mẽ lắm. Cho chúng thấy ai mới thật sự nắm giữ sức mạnh!",
STAGE_7_TITLE = "Chiến tranh trước Bắc",
STAGE_8_DESCRIPTION = "Chiến thắng khá đấy! Ngươi đã khiến cả miền Bắc cảnh giác. Nhanh lên! Trước khi viện binh của chúng tới, hãy xuôi theo dòng nước giá lạnh và chiếm ngôi làng chính. Tự cân nhắc lực lượng của ngươi, tướng quân. Đừng làm ta thất vọng!",
STAGE_8_TITLE = "Căng chảy",
STAGE_9_DESCRIPTION = "Chết tiệt! Băng trên dòng nước đã vỡ trong trận chiến, khiến quân ta tổn thất nặng. Ta phải cho lũ phương Bắc thấy chúng ta vẫn đáng sợ! Ngôi làng của chúng đã ở trong tầm tay. Hãy chiếm lấy và mang đi mọi thứ có thể. Chúng sẽ hối hận vì dám chống lại ta!",
STAGE_9_TITLE = "Làng Bắc",
TAP_TO_CONTINUE = "Nhấp vào để tiếp tục.",
THIEF_NAME = "Goblin trộm vàng",
TIP_1 = "Nhấn vào kẻ địch để xem thông tin và tìm cách đối phó phù hợp.",
TIP_10 = "Kẻ địch bay không bị binh sĩ chặn lại và phần lớn tháp pháo không thể nhắm vào chúng.",
TIP_11 = "Soul Impact có độ trễ ngắn trước khi gây sát thương. Hãy nhắm đón đầu mục tiêu.",
TIP_12 = "Vật phẩm mạnh trong cửa hàng có thể giúp bạn xoay chuyển cả trận chiến!",
TIP_2 = "Sát thương phép rất hiệu quả trước kẻ địch có giáp vật lý cao.",
TIP_3 = "Khi các doanh trại được nâng cấp, một nhóm các binh sĩ mới sẽ chạy ra và chiến đấu thay cho những đồng chí mệt mỏi của họ.",
TIP_4 = "Gọi đợt địch đến sớm để nhận thêm vàng và giảm thời gian hồi chiêu kỹ năng.",
TIP_5 = "Thay đổi điểm tập kết của doanh trại để đưa binh sĩ đến vị trí có lợi.",
TIP_6 = "Chú ý lá cờ đợt địch tiếp theo để biết trước kẻ địch sắp xuất hiện và chuẩn bị đối phó!",
TIP_7 = "Hầu hết đòn đánh diện rộng có thể gây sát thương cho kẻ địch bay dù không nhắm trực tiếp vào chúng.",
TIP_8 = "Bán tháp kém hiệu quả có thể giúp bạn có đủ vàng để xoay chuyển tình thế.",
TIP_9 = "Nâng cấp tháp thường hiệu quả hơn xây nhiều tháp cấp thấp.",
