ENEMY_DENAS_FINAL_END_TAUNT_1 = "Xin lỗi, chúng tôi đã đóng cửa, ngày nào đó lại đến.",
STAGE_17_DESCRIPTION = "Những chiến thắng gần đây dường như khiến ai cũng muốn tranh phần. Tộc Anurian từng rời lục địa này nay đã trở lại. Những tinh thể hùng mạnh của chúng rất cần cho kế hoạch tương lai của ta. Chiếm vùng đất ấy và cho chúng biết mình không xứng đáng sống dưới ánh sáng!",
STAGE_17_TITLE = "Biển Maghriensia",
STAGE_18_DESCRIPTION = "Nhìn kìa, tướng quân! Quân ta đã xuất hiện và kẻ địch chỉ biết bỏ chạy. Đánh bại lực lượng còn lại là vùng đất này sẽ thuộc về ta. Nhưng cẩn thận... ta cảm thấy một luồng ma lực quen thuộc. Nếu đúng là sức mạnh hắc ám đó, phải ngăn chúng ngay, không được chậm trễ!",
STAGE_18_TITLE = "Khu vực Anurie",
STAGE_19_DESCRIPTION = "Điều ta lo cuối cùng cũng xảy ra. Polyx the Wise đã bị tha hóa vì nghiên cứu những bí thuật cấm. Hắn tưởng có thể kiểm soát sức mạnh hắc ám mà không phải trả giá sao? Hạ hắn cùng đám tay sai trước khi chúng làm ô nhiễm cả vùng đất. Không được thất bại!",
STAGE_19_TITLE = "Hồ khôn ngoan",
COMIC_ANURIANS_FRAME1 = "Nhiều năm trước, chúng ta rời vùng đất này để tìm kiếm sức mạnh và tri thức.",
COMIC_ANURIANS_FRAME2 = "Từ đó, những dân tộc thấp kém liên tục nổi loạn. Nhưng mọi chuyện sẽ chấm dứt.",
