STAGE_27_DESCRIPTION = "Giờ phải tiến vào đầm lầy mục nát, nơi nguy hiểm nhất Varlad. Chúng ta không thể bỏ qua nó: kẻ địch tập trung ở đây có thể đánh úp hậu quân khi ta tiến lên phía bắc. Hãy cẩn thận với những sinh vật bất tử hùng mạnh trong vùng.",
STAGE_27_TITLE = "Một đêm trong hồ",
