STAGE_28_DESCRIPTION = "Cuối cùng cũng đến nơi. Đây sẽ là trận cuối để chấm dứt mối đe dọa này mãi mãi. Kẻ địch sẽ dùng toàn bộ lực lượng tiêu diệt quân ta, và ngươi cũng phải dốc hết sức. Các linh hồn cổ đã tích tụ quá nhiều năng lượng. Ngươi chỉ cần làm chúng suy yếu, việc phong ấn cứ để ta lo.",
