COMIC_DINO_FRAME2 = "Đôi khi, ngay cả trong nghịch cảnh, vận may vẫn mỉm cười...",
COMIC_DINO_FRAME3 = "Mở ra một cơ hội mới.",
COMIC_DINO_FRAME4 = "Cả một thế giới đầy cơ hội, nơi việc nổi dậy không còn là giấc mơ viển vông.",
STAGE_29_DESCRIPTION = "Ra là vậy! Chúng đã lên kế hoạch từ lâu, lợi dụng công việc đào mỏ để chuẩn bị nổi loạn. Thông minh thật. Chỉ cần nhường lũ người lùn một chút đất, chúng sẽ đào cả thế giới ngầm rồi dùng nó chống lại ngươi! Đã đến lúc dạy chúng một bài học.",
STAGE_29_TITLE = "Khai thác",
STAGE_30_DESCRIPTION = "Không ổn rồi. Thế giới ngầm rộng hơn ta tưởng, và thứ gì ở đây cũng muốn ăn thịt mọi thứ khác. Nếu lũ người lùn lông lá chịu tắm, có lẽ ta còn nhận chúng vào quân đội. Còn khủng long thì miễn bàn. Chúng ta sẽ chặn chúng ngay tại đây!",
STAGE_30_TITLE = "Lối đi mất",
STAGE_31_DESCRIPTION = "Chúng đào sâu đến mức này, quả là kỳ công, nhưng chẳng cứu nổi chúng đâu. Cuộc nổi loạn nhỏ bé này sẽ kết thúc tại đây. Còn lũ sinh vật kia... ta sẽ cho chúng hiểu vì sao chúng bị vùi dưới lòng đất, để chúng không bao giờ dám chống lại ta nữa!",
STAGE_31_NAME = "Thế giới nguyên bản",
HERO_MAMMOTH_CLASS = "Bạo chúa cổ đại",
HERO_MAMMOTH_DESCRIPTION = "Quân tử báo thù, mười năm chưa muộn. Grosh hiểu rõ điều đó. Hắn chờ năm này qua năm khác để trở về thế giới của mình và thực hiện kế hoạch trả thù. Cuối cùng cơ hội đã đến: tiêu diệt kẻ thù trước khi chúng kịp tiêu diệt hắn.",

