STAGE_32_DESCRIPTION = "Hải quân của ta đã âm thầm đến bờ biển Hammerhold. Tướng quân, khi pháo hạm bắn hạ tháp địch, hãy đổ bộ và chiếm khu vực. Chuẩn bị thật chu đáo: lần này chúng ta sẽ kết thúc vài huyền thoại.",
STAGE_32_NAME = "Bóng ma lặn",
STAGE_33_DESCRIPTION = "Ta chẳng thấy cuộc đón tiếp này ấn tượng chút nào. Chúng ta đã vào tận nhà mà chúng chỉ chống cự được thế sao? Khoan... đó là Mirage nổi tiếng phải không? Cẩn thận, tướng quân. Cô ta thích những trò bẩn, hãy đề phòng ảo ảnh và mưu mẹo.",
STAGE_33_NAME = "Sapa Ocean",
STAGE_34_DESCRIPTION = "Đội trinh sát vẫn chưa trở về. Những kẻ sống sót vừa sợ hãi vừa kiệt sức, chỉ biết lắp bắp rằng có thứ gì đó trong kim tự tháp. Nếu có sức mạnh ẩn dưới thung lũng này, ta muốn chiếm lấy nó. Chuẩn bị tiến vào điều tra.",
STAGE_34_NAME = "Đế quốc bị mất",
STAGE_35_DESCRIPTION = "Cổng Hammerhold. Phải thừa nhận trông khá ấn tượng, nhưng cũng chẳng chịu nổi một quả cầu lửa đặt đúng chỗ. Lạ là Malik không đứng trên tường thành cùng binh sĩ. Gần đây hắn có vẻ quá tự mãn, cứ như một Denas nữa vậy. Chiếm thành cho ta, tướng quân!",
STAGE_35_TITLE = "Phố Hammerhold",
STAGE_36_DESCRIPTION = "Thật bất ngờ, Malik thách đấu ta tại đấu trường Hammerhold. Theo truyền thống cổ, ai thắng thử thách sa mạc sẽ trở thành vua của thành phố. Chúng cũng chẳng còn lựa chọn, nhưng cách này giúp ta khỏi phải dẹp một cuộc nổi loạn phiền phức.",
STAGE_36_TITLE = "Sân vận động lớn",
