STAGE_37_DESCRIPTION = "Lũ hải tặc đã chạy trốn. Khí phách của chúng đâu rồi? Không quan trọng, ta sẽ đuổi theo. Biển cả là chặng tiếp theo của chúng ta, tướng quân. Mang cờ của chúng về cho ta!",
STAGE_37_TITLE = "Cảnh sát Cướp biển",
STAGE_38_DESCRIPTION = "Một huyền thoại hải tặc mà lại kết thúc như vậy, thật đáng thất vọng. Giờ chúng ta phải đánh nhau với lũ khỉ sao? Hãy cho chúng biết quân ta đến đây để chinh phạt, chẳng phải để làm trò với chúng!",
STAGE_38_TITLE = "Đảo may mắn",
STAGE_39_DESCRIPTION = "Ai ngờ lũ khỉ có thể gây lắm rắc rối đến thế. Con mồi tiếp theo là gì, cá sao? Ta chẳng thấy con cá nào cả. Đừng chủ quan, tướng quân. Ta đã ngửi thấy mùi phục kích từ xa.",
STAGE_39_TITLE = "Đồ cá mập",
STAGE_40_DESCRIPTION = "Mùi chết chóc tràn ngập không khí. Hòn đảo này dường như đầy linh hồn hải tặc. Quân ta có thể tuyển thêm vài binh sĩ mới. Hãy cho chúng biết: được phụng sự ta sau khi chết chính là nơi an nghỉ tốt nhất. Ha ha ha!",
STAGE_40_TITLE = "Vịnh thuyền sập",
STAGE_41_DESCRIPTION = "Lũ xảo quyệt lại thoát khỏi tay chúng ta rồi, tướng quân. Nhưng đừng lo! Những vỏ chuối chúng vứt xuống biển vô tình để lại dấu vết dẫn tới hòn đảo bí mật. Đã đến lúc bắt đám vô pháp ấy quỳ xuống xin tha!",
